).trim();

const eventName = String(
  root.event ??
  root.eventType ??
  root.type ??
  ''
).trim();

const normalizedEventName = eventName
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '_');

// SEND_MESSAGE Ã© um evento tÃ©cnico gerado pelo prÃ³prio envio da Evolution.
// O MESSAGES_UPSERT continua disponÃ­vel para detectar mensagens manuais do atendente.
const isTechnicalSendMessageEvent =
  normalizedEventName === 'send_message' ||
  normalizedEventName.endsWith('_send_message') ||
  normalizedEventName.includes('send_message');

return [{
  json: {
    instance:
      root.instance ??
      root.instanceName ??
      payload.instance ??
      'miranda-express',

    event: eventName || null,

    remoteJid,
    number,
    customerName,
    messageId,
    text,
    fromMe,
    isGroup,

    // Mensagem prÃ³pria precisa seguir pelo ramo de detecÃ§Ã£o humana,
    // mesmo quando o texto estiver vazio em algum evento da Evolution.
    shouldProcess:
      !isGroup &&
      !isTechnicalSendMessageEvent &&
      Boolean(number) &&
      (fromMe || Boolean(text)),

    debug_from_me_raw: fromMeRaw
  }
}];

const c = $('ConfiguraÃ§Ã£o Geral1').first().json;

const sr = $('Buscar SessÃ£o').first().json;

// v23.9.4: normaliza qualquer formato de resposta do HTTP Request do Supabase
// e escolhe sempre a sessÃ£o mais recentemente atualizada.
const decodeStreamResponse = value => {
  if (!value || typeof value !== 'object') return value;

  const buffers =
