const scoreCompatibilityRow = (row, search) => {
  if (!search) return 0;

  const rowTerms = [
    row.brand,
    row.model,
    row.device_name,
    row.full_name,
    ...(Array.isArray(row.aliases) ? row.aliases : [])
  ]
    .filter(Boolean)
    .map(normalizeDeviceText);

  const searchTokens = search.split(' ').filter(token => token.length >= 2);
  let score = 0;

  for (const term of rowTerms) {
    if (!term) continue;

    if (term === search) {
      score = Math.max(score, 100);
      continue;
    }

    if (term.includes(search) || search.includes(term)) {
      score = Math.max(score, 85);
    }

    const termTokens = term.split(' ').filter(token => token.length >= 2);
    const hits = searchTokens.filter(token => termTokens.includes(token)).length;
    const modelTokens = searchTokens.filter(token => /\d/.test(token));
    const modelHits = modelTokens.filter(token => termTokens.includes(token)).length;

    score = Math.max(score, hits * 15 + modelHits * 25);
  }

  return score;
};

