      : `Entregamos em ${state.neighborhood}. A taxa Ã© R$ ${money(state.delivery_fee)}. Agora envie o endereÃ§o completo da entrega.`;
  }
} else {
  state.delivery_fee = null;
  if (!base.preserveCurrentReply) {
    reply =
      `NÃ£o encontrei ${state.neighborhood} na tabela de entrega. ` +
