const decodeBufferLike = value => {
  if (!value || typeof value !== 'object') return value;

  const candidates = [
    value?._readableState?.buffer,
    value?.body?._readableState?.buffer,
    value?.data?._readableState?.buffer
  ].filter(Boolean);

  for (const buffer of candidates) {
    const chunks = [];

    if (Array.isArray(buffer)) {
      chunks.push(...buffer);
    } else if (buffer?.head) {
      let cursor = buffer.head;
      let safety = 0;
      while (cursor && safety++ < 1000) {
        chunks.push(cursor.data ?? cursor);
        cursor = cursor.next;
      }
    }

    const bytes = [];
    for (const chunk of chunks) {
      const data =
        Array.isArray(chunk) ? chunk :
        Array.isArray(chunk?.data) ? chunk.data :
        Array.isArray(chunk?.chunk?.data) ? chunk.chunk.data :
        Array.isArray(chunk?.buffer?.data) ? chunk.buffer.data :
        null;
      if (data) bytes.push(...data);
    }

    if (bytes.length) {
      try {
        const text = Buffer.from(bytes).toString('utf8').trim();
        if (text) return JSON.parse(text);
      } catch {}
    }
  }

  return value;
};

const collectRows = (value, rows = [], seen = new Set(), depth = 0) => {
  if (depth > 20 || value === null || value === undefined) return rows;

  const decoded = decodeBufferLike(value);
  if (decoded !== value) return collectRows(decoded, rows, seen, depth + 1);

  if (typeof value !== 'object') return rows;
  if (seen.has(value)) return rows;
  seen.add(value);

  if (Array.isArray(value)) {
    for (const item of value) collectRows(item, rows, seen, depth + 1);
    return rows;
  }

  if (value.customer_number) rows.push(value);

  for (const child of Object.values(value)) {
    collectRows(child, rows, seen, depth + 1);
  }

  return rows;
};

const customerNumber = String(base?.state?.customer_number ?? base?.number ?? '');
const persistedRows = collectRows(raw)
  .filter(row => String(row.customer_number ?? '') === customerNumber)
