const orderLabel = orderNumber ? ` nÂº ${orderNumber}` : '';
const isThanks = /\b(obrigado|obrigada|valeu|agradeco|agradeÃ§o|obg|vlw)\b/.test(normalized);
const asksIfConfirmed =
  /(?:ja|jÃ¡).*(?:confirmei|confirmado)/.test(normalized) ||
