    : `Seu pedido${orderLabel} jÃ¡ estÃ¡ confirmado. Para fazer outro, escreva NOVO PEDIDO.`;

state.status = finalizedStatuses.has(persistedStatus) ? persistedStatus : 'reserved';
state.order_id = persisted.order_id ?? state.order_id ?? null;
